+					>
+						Cancel
+					</Button>
+				</div>
+			{/if}
+		{/if}
+
+		{#if actionError}
+			<p class="text-sm text-destructive" data-testid="action-error">{actionError}</p>
+		{/if}
+
+		<Separator />
+
+		<!-- Todos -->
