+  and the task list Sheet panel. Handles all task display, actions, and notes.
+-->
+<script lang="ts">
+	import type { TaskDetail } from '@kynetic-ai/shared';
+	import {
+		startTask,
+		submitTask,
+		completeTask,
+		blockTask,
+		addTaskNote
+	} from '$lib/api';
